192	<script>
193	(function(){
194	  var LAYOUT_KEY = 'coach888_layout';
195	  var TITLES_KEY = 'coach888_titles';
196	  var BADGES_KEY = 'coach888_badges';
197	
198	  function renumber(grid){
199	    grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
200	    var title = grid.previousElementSibling;
201	    if (title && title.classList.contains('section-title')) {
202	      var countEl = title.querySelector('.count');
203	      if (countEl) countEl.textContent = grid.querySelectorAll('.item').length + '項';
204	    }
205	  }
206	
207	  function saveLayout(){
208	    var layout = {};
209	    document.querySelectorAll('.grid').forEach(function(grid){
210	      layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
211	    });
212	    localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
213	    // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
214	    document.querySelectorAll('.grid').forEach(function(grid){
215	      localStorage.removeItem('coach888_order_' + grid.dataset.section);
216	    });
217	  }
218	
219	  function loadLayout(){
220	    var raw = localStorage.getItem(LAYOUT_KEY);
221	    if (raw) {
222	      try { return JSON.parse(raw); } catch(e){}
223	    }
224	    // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
225	    var legacy = {}, found = false;
226	    document.querySelectorAll('.grid').forEach(function(grid){
227	      var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
228	      if (old) {
229	        try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
230	      }
231	    });
232	    return found ? legacy : null;
233	  }
234	
235	  function saveTitles(){
236	    var titles = {};
237	    document.querySelectorAll('.section-title').forEach(function(t){
238	      var span = t.querySelector('.title-text');
239	      if (span) titles[t.dataset.section] = span.textContent.trim();
240	    });
241	    localStorage.setItem(TITLES_KEY, JSON.stringify(titles));
242	  }
243	
244	  function applyTitles(){
245	    var raw = localStorage.getItem(TITLES_KEY);
246	    if (!raw) return;
247	    try {
248	      var titles = JSON.parse(raw);
249	      document.querySelectorAll('.section-title').forEach(function(t){
250	        var span = t.querySelector('.title-text');
251	        if (span && titles[t.dataset.section] != null) span.textContent = titles[t.dataset.section];
252	      });
253	    } catch(e){}
254	  }
255	
256	  function saveBadges(){
257	    var badges = {};
258	    document.querySelectorAll('.item').forEach(function(it){
259	      var b = it.querySelector('.badge');
260	      if (b) badges[it.dataset.url] = b.textContent.trim();
261	    });
262	    localStorage.setItem(BADGES_KEY, JSON.stringify(badges));
263	  }
264	
265	  function applyBadges(){
266	    var raw = localStorage.getItem(BADGES_KEY);
267	    if (!raw) return;
268	    try {
269	      var badges = JSON.parse(raw);
270	      document.querySelectorAll('.item').forEach(function(it){
271	        var b = it.querySelector('.badge');
272	        if (b && badges[it.dataset.url] != null) b.textContent = badges[it.dataset.url];
273	      });
274	    } catch(e){}
275	  }
276	
277	  function bindEditable(el, onSave){
278	    el.addEventListener('keydown', function(e){
279	      if (e.key === 'Enter') { e.preventDefault(); el.blur(); }
280	    });
281	    el.addEventListener('blur', onSave);
282	  }
283	
284	  function applyLayout(){
285	    var layout = loadLayout();
286	    if (!layout) return;
287	    var allItems = {};
288	    document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
289	    document.querySelectorAll('.grid').forEach(function(grid){
290	      var ids = layout[grid.dataset.section];
291	      if (!ids) return;
292	      ids.forEach(function(id){
293	        if (allItems[id]) grid.appendChild(allItems[id]);
294	      });
295	    });
296	  }
297	
298	  function getDragAfterElement(grid, y){
299	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
300	    return els.reduce(function(closest, child){
301	      var box = child.getBoundingClientRect();
302	      var offset = y - box.top - box.height / 2;
303	      if (offset < 0 && offset > closest.offset) {
304	        return { offset: offset, element: child };
305	      }
306	      return closest;
307	    }, { offset: -Infinity, element: null }).element;
308	  }
309	
310	  // 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
311	  // .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
312	  // 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
313	  // 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
314	  // drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
315	  // 拖放機制，也就不會有這個衝突。
316	  var dragEl = null;
317	  var sourceGrid = null;
318	
319	  function onMouseMove(e){
320	    if (!dragEl) return;
321	    var el = document.elementFromPoint(e.clientX, e.clientY);
322	    var targetGrid = el ? el.closest('.grid') : null;
323	    if (!targetGrid) return;
324	    var afterEl = getDragAfterElement(targetGrid, e.clientY);
325	    if (afterEl == null) {
326	      targetGrid.appendChild(dragEl);
327	    } else if (afterEl !== dragEl) {
328	      targetGrid.insertBefore(dragEl, afterEl);
329	    }
330	  }
331	
332	  function onMouseUp(){
333	    if (!dragEl) return;
334	    dragEl.classList.remove('dragging');
335	    var targetGrid = dragEl.closest('.grid');
336	    renumber(sourceGrid);
337	    if (targetGrid !== sourceGrid) renumber(targetGrid);
338	    saveLayout();
339	    dragEl = null;
340	    sourceGrid = null;
341	    document.removeEventListener('mousemove', onMouseMove);
342	    document.removeEventListener('mouseup', onMouseUp);
343	  }
344	
345	  applyLayout();
346	  applyTitles();
347	  applyBadges();
348	
349	  document.querySelectorAll('.item').forEach(function(item){
350	    var handle = item.querySelector('.drag-handle');
351	    handle.addEventListener('mousedown', function(e){
352	      e.preventDefault();
353	      dragEl = item;
354	      sourceGrid = item.closest('.grid');
355	      item.classList.add('dragging');
356	      document.addEventListener('mousemove', onMouseMove);
357	      document.addEventListener('mouseup', onMouseUp);
358	    });
359	  });
360	
361	  document.querySelectorAll('.title-text').forEach(function(el){ bindEditable(el, saveTitles); });
362	  document.querySelectorAll('.badge').forEach(function(el){ bindEditable(el, saveBadges); });
363	
364	  document.querySelectorAll('.grid').forEach(renumber);
365	
366	  var toastEl = document.getElementById('toast');
367	  function toast(msg){
368	    toastEl.textContent = msg;
369	    toastEl.classList.add('show');
370	    setTimeout(function(){ toastEl.classList.remove('show'); }, 2200);
371	  }
372	
373	  document.getElementById('btnCopy').addEventListener('click', function(){
374	    var lines = [];
375	    document.querySelectorAll('.section-title').forEach(function(title, idx){
376	      var grid = document.querySelectorAll('.grid')[idx];
377	      lines.push(title.textContent.trim());
378	      grid.querySelectorAll('.item').forEach(function(item){
379	        var num = item.querySelector('.num').textContent;
380	        var name = item.querySelector('.name').textContent;
381	        var url = item.dataset.url;
382	        var badge = item.querySelector('.badge').textContent.trim();
383	        lines.push('  ' + num + '. ' + name + '  ' + url + '  [' + badge + ']');
384	      });
385	      lines.push('');
386	    });
387	    var text = lines.join('\n');
388	    navigator.clipboard.writeText(text).then(function(){
389	      toast('已複製目前排序，貼給小龍蝦即可固化進正式檔案');
390	    }, function(){
391	      toast('複製失敗，請手動選取畫面上的文字');
392	    });
393	  });
394	})();
395	</script>
396	</body>
